#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
#
# Regenerate Braids' resource tables for the FM-1's sample rate.
#
#   scripts/gen-braids-resources.sh [RATE]        default 44100
#
# WHY. Braids runs at 96 kHz; the FM-1 at 44.1 kHz. Its tables are generated by
# braids/resources/*.py from a single `sample_rate` variable, and several are
# calibrated in seconds or absolute Hz rather than in phase increments:
#
#   oscillator_increments, oscillator_delays   pitch
#   svf_cutoff / svf_damp / svf_scale          filter cutoffs
#   resonator_coefficient / resonator_scale    resonator tuning
#   bowing_* / blowing_* envelopes             attack and decay times
#   granular_envelope_rate                     grain rate
#
# Running the 96 kHz tables at 44.1 kHz leaves pitch fixable with a constant
# offset (see dsp/mi/fm1_braids.h) but makes every envelope and filter run
# 96000/44100 = 2.18x fast. Regenerating at 44100 fixes all of it at the source
# and makes the pitch offset unnecessary.
#
# HOW. MI's generators are Python 2 and predate modern numpy. Rather than edit
# the upstream sources, this copies them to a temp directory and applies the
# minimum set of mechanical fixes there, so references/eurorack stays pristine.
#
# Output: dsp/mi/braids/resources.cc and resources.h
set -euo pipefail

RATE="${1:-44100}"
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
E="${EURORACK:-$ROOT/references/eurorack}"
VENV="${JIELI_VENV:-$HOME/.jieli/venv}"
PY="$VENV/bin/python"
DEST="$ROOT/dsp/mi/braids"

[ -d "$E/braids/resources" ] || { echo "no eurorack clone at $E"; exit 2; }
[ -x "$PY" ] || { echo "no venv python at $PY (run scripts/setup-wsl-toolchain.sh)"; exit 2; }
"$PY" -c 'import numpy' 2>/dev/null || "$VENV/bin/pip" install --quiet numpy

W="$(mktemp -d)"; trap 'rm -rf "$W"' EXIT
cp -r "$E/stmlib" "$W/stmlib"
mkdir -p "$W/braids"
cp -r "$E/braids/resources" "$W/braids/resources"
cp -r "$E/braids/data" "$W/braids/data"      # waves.bin / map.bin, read by waveforms.py

SHA="$(git -C "$E" rev-parse HEAD)"
echo "eurorack $SHA -> resources at $RATE Hz"

# --- mechanical fixes, applied to the temp copies only ----------------------
"$PY" - "$W" "$RATE" <<'PATCH'
import pathlib, re, sys
w, rate = pathlib.Path(sys.argv[1]), sys.argv[2]

# 1. `print x` -> `print(x)` across the generators and the compiler
for f in list((w / "braids/resources").glob("*.py")) + list((w / "stmlib/tools").glob("*.py")):
    t = f.read_text()
    t = re.sub(r'^(\s*)print (?!\()(.+)$', r'\1print(\2)', t, flags=re.M)
    f.write_text(t)

lt = w / "braids/resources/lookup_tables.py"
t = lt.read_text()

# 2. the sample rate: the whole point of this script.
#    count=1 is essential. lookup_tables.py REASSIGNS `sample_rate = 48000`
#    later, in the envelope-increments section, deliberately pinning envelope
#    rates to 48 kHz independently of the audio rate. Replacing both
#    occurrences silently corrupts lut_env_portamento_increments (caught by
#    regenerating at 96000 and diffing against upstream).
n_all = len(re.findall(r'^sample_rate\s*=\s*\d+', t, flags=re.M))
t, n_sub = re.subn(r'^sample_rate\s*=\s*\d+', f'sample_rate = {rate}', t, count=1, flags=re.M)
# Check the pattern MATCHED, not that the text changed -- regenerating at
# Braids' native 96000 is a no-op substitution and must still succeed.
assert n_sub == 1, "no sample_rate assignment found in lookup_tables.py"
print(f"  sample_rate: {n_all} assignment(s) present, first set to {rate}")

# 3. py2 int division used as a count/index. The generators use an explicit
#    `.0` wherever float division was meant, so only int/int sites change.
t = t.replace("n = size / ratio", "n = size // ratio")
lt.write_text(t)

wf = w / "braids/resources/waveforms.py"
t = wf.read_text()

# 4. numpy >= 1.12 refuses float arrays as indices. fmod() returns floats and
#    wrap/quadrature/fill are used to index waveform arrays.
anchor = "waveforms.append(('sine', scale(sine[quadrature])))"
cast = ("wrap = wrap.astype(int)\n"
        "quadrature = quadrature.astype(int)\n"
        "fill = fill.astype(int)\n")
if anchor in t and "quadrature.astype(int)" not in t:
    t = t.replace(anchor, cast + anchor, 1)

# 5. scalar int division used as an index (WAVETABLE_SIZE is 256, so integer
#    division is exact and changes nothing numerically).
t = t.replace("pulse[WAVETABLE_SIZE / 2]", "pulse[WAVETABLE_SIZE // 2]")

# 6. py2 `file()` is gone, and in py3 reading 'rb' already yields ints, so
#    map(ord, ...) would be ord(int). list(bytes) gives the same values py2's
#    map(ord, str) did.
t = re.sub(r"map\(ord,\s*file\((.+?),\s*'rb'\)\.read\(\)\)",
           r"list(open(\1, 'rb').read())", t)
wf.write_text(t)

# 7. the compiler itself: py2's two-argument str.translate(table, deletechars)
#    has no py3 equivalent, but str.maketrans's three-argument form does both
#    (map these, delete those).
rc = w / "stmlib/tools/resources_compiler.py"
t = rc.read_text()
t = t.replace(
    "table = string.maketrans(in_chr, ''.join(map(chr, out_chr)))",
    "table = None  # replaced below: py3 builds it with the delete set included")
t = t.replace(
    "self._MakeIdentifier = lambda s:s.translate(table, bad_chars)",
    "self._MakeIdentifier = lambda s: s.translate("
    "str.maketrans(in_chr, ''.join(map(chr, out_chr)), bad_chars))")

# 8. py2 file() writing text in binary mode -- both output files.
t = t.replace("f = file(os.path.join(root.target, 'resources.h'), 'wb')",
              "f = open(os.path.join(root.target, 'resources.h'), 'w')")
t = t.replace("f = file(file_name, 'wb')",
              "f = open(file_name, 'w')")
rc.write_text(t)

print("  patched: print(), sample_rate, int division, numpy index casts,")
print("           py3 file()/map(ord) on binary wavetables, str.translate")
PATCH

# --- run MI's own compiler under python3 ------------------------------------
cat > "$W/run_compiler.py" <<'PY'
import builtins, os, runpy, string, sys
builtins.xrange = range          # py2 builtins the compiler still uses
builtins.unicode = str
builtins.long = int
# py2 string module constants, renamed in py3
string.uppercase = string.ascii_uppercase
string.lowercase = string.ascii_lowercase
string.letters   = string.ascii_letters
sys.path.insert(0, os.path.abspath('braids/resources'))   # implicit relative imports
sys.path.insert(0, os.path.abspath('.'))
sys.argv = ['resources_compiler.py', 'braids/resources/resources.py']
runpy.run_path('stmlib/tools/resources_compiler.py', run_name='__main__')
PY

( cd "$W" && "$PY" run_compiler.py )

[ -f "$W/braids/resources.cc" ] || { echo "compiler produced no resources.cc"; exit 1; }

mkdir -p "$DEST"
cp "$W/braids/resources.cc" "$W/braids/resources.h" "$DEST/"

{
    echo "# Braids resources, regenerated"
    echo
    echo "Generated by \`scripts/gen-braids-resources.sh $RATE\` from"
    echo "pichenettes/eurorack \`$SHA\`, MIT, (c) Emilie Gillet."
    echo
    echo "**sample_rate = $RATE** (upstream ships 96000)."
    echo
    echo "\`resources.cc\` and \`resources.h\` in this directory are therefore"
    echo "GENERATED, not copied verbatim -- unlike every other vendored file."
    echo "Re-run the script rather than editing them."
} > "$DEST/RESOURCES_GENERATED.md"

echo "  wrote $DEST/resources.cc  ($(stat -c%s "$DEST/resources.cc") B)"
echo "  wrote $DEST/resources.h   ($(stat -c%s "$DEST/resources.h") B)"
